Translate("ruRU", "abercrombie", {
	title = "Аберкромби",
	subtitle = "Отшельник Вороньего Холма",
	found = "Хижина на северном краю Кладбища Вороньего Холма",
	hint = [=[Навестите старого отшельника, который живет в хижине над Кладбищем Вороньего Холма.]=],
	allegiance = "Нет",
	aliases = { "Бальзамировщик" },
	sections = {
		{
			title = "Обзор",
			text = [=[Аберкромби кажется дряхлым стариком, который живет один в хижине над Кладбищем Вороньего Холма. Он больше не отваживается на дорогу в город и просит прохожих о мелких услугах: нить, крепкая выпивка, кости вурдалаков для пугала, ящик, доставшийся {link:ogres}огр{/link}ам. Он благодарен и много смеется. И он же — Бальзамировщик.]=],
		},
		{
			title = "Значение",
			text = [=[Дети Темнолесья знают Бальзамировщика по сказке на ночь. Он был добрым алхимиком, и когда его жена {link:elysa}Элиза{/link} умерла, горе свело его с ума. Чтобы вернуть ее, он вложил в ее грудь собственное сердце. Она восстала вновь, жаждая человеческой плоти, и ему пришлось держать ее п{link:ogres}огр{/link}ебенной. Эта история — правда, и Бальзамировщик живет рядом с ее могилой.]=],
		},
		{
			title = "Деяния",
			text = [=[• Чужими руками он собрал нить из волос призрака, зомбячий сок и ребра вурдалаков.
• Он создал существо из плоти, кости и металла, чтобы наслать его на {link:darkshire}Темнолесье{/link}.
• Он написал мэру письмом, которого никто в городе не мог прочесть.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Настоящее имя отшельника, его возраст и годы его безумия нигде не записаны.]=],
		},
	},
	chapters = {
		{
			title = "Просьбы старика",
			hint = "Помогите отшельнику с тем, чего он не может добыть сам.",
			text = [=[Нить, говорил он, нужна для дверей и окон, чтобы не пускать духов. Сок — чтобы с{link:ogres}огр{/link}еваться холодными ночами. Ребра — для пугала против вурдалаков. Каждая вещь сама по себе была безобидна. Каждая пошла на одно и то же дело.]=],
		},
		{
			title = "Существо у двери",
			hint = "Узнайте, что на самом деле сказано в письме отшельника.",
			text = [=[В переводе письмо оказалось похвальбой. Аберкромби называл себя творцом. Его новейшее творение ждало у хижины, скрежеща зубами, готовое по его слову выступить на {link:darkshire}Темнолесье{/link}. Чужак, который ему помогал, построил это существо, сам того не ведая.]=],
		},
	},
	mentions = {
		{ text = "Отшельник" },
		{ text = "Доставьте нить" },
		{ text = "Доставка сока" },
		{ text = "Вурдалачье чучело" },
		{ text = "{link:ogres}Огры{/link}-воры" },
		{ text = "Записка для мэра" },
	},
	bonds = {
		{ id = "eliza", name = "Элиза", note = "его жена" },
		{ id = "stitches", name = "Стежок", note = "его творение" },
		{ id = "lord-ello-ebonlocke", name = "Лорд Элло Чернодрев", note = "прочел его письмо" },
		{ id = "madame-eva", name = "Мадам Ева", note = "сделала для него нить" },
	},
})

Translate("ruRU", "eliza", {
	title = "Элиза",
	subtitle = "Невеста Бальзамировщика",
	found = [=[Ее могила возле хижины отшельника, над Кладбищем Вороньего Холма]=],
	hint = "Найдите могилу, что лежит возле хижины отшельника.",
	allegiance = "Бальзамировщик",
	sections = {
		{
			title = "Обзор",
			text = [=[{link:elysa}Элиза{/link} была женой алхимика, который стал {link:abercrombie}Бальзамировщик{/link}ом. Когда она умерла, он не смог ее отпустить. Он отдал ей собственное сердце, и она восстала из мертвых. Но восстала не та женщина, которую он любил. Она пробудилась, жаждая плоти живых, и муж похоронил ее снова, чтобы уберечь от нее мир.]=],
