			title = "Вскрытая могила",
			hint = "Раскопайте могилу возле хижины отшельника.",
			text = [=[Земля над могилой была рыхлой, словно ее не раз раскапывали и засыпали вновь. Под ней лежал гроб, а изнутри доносились скрежет когтей и скрип гнилых зубов. Когда крышку подняли, {link:elysa}Элиза{/link} вышла наружу. Сердце вынули из нее еще бьющимся. Мэр Темнолесья назвал его защитой от зла безумца и поклялся, что имя того, кто его принес, навсегда останется в летописях города.]=],
		},
	},
	mentions = {
		{ text = "Невеста {link:abercrombie}Бальзамировщик{/link}а" },
		{ text = "Раскапывая землю" },
	},
	bonds = {
		{ id = "abercrombie", name = "Аберкромби", note = "ее муж" },
		{ id = "lord-ello-ebonlocke", name = "Лорд Элло Чернодрев", note = "послал за сердцем ее мужа" },
	},
})

Translate("ruRU", "stalvan-mistmantle", {
