Translate("ruRU", "mor-ladim", {
	title = "Мор'Ладим",
	subtitle = "Рыцарь без покоя",
	found = "Бродит по Кладбищу Вороньего Холма",
	hint = [=[Сразитесь с мертвым рыцарем, который бродит по Кладбищу Вороньего Холма.]=],
	allegiance = "Нет",
	aliases = { "Морган Ладимор" },
	sections = {
		{
			title = "Обзор",
			text = [=[Морган Ладимор был рыцарем, который сражался за невинных и бедных. В восемнадцать лет он женился на девушке по имени Лис, и у них родились сын и две дочери. Когда война пришла в земли {link:lordaeron}Лордерона{/link}, он ушел на север сражаться бок о бок с паладином {link:uther-the-lightbringer}Утером Светоносным{/link}. Вернувшись домой, он нашел свой лес сгнившим, а дом — в руинах. Теперь он бродит по кладбищу под именем Мор'Ладим — мертвая тварь, убивающая без причины.]=],
		},
		{
			title = "Значение",
			text = [=[Падение этого рыцаря — самое печальное предание Сумеречного леса. Он был добрым человеком, которого сломило горе. Его имя — предостережение о том, что тьма леса способна сделать даже с самым сильным сердцем.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он служил паладину {link:uther-the-lightbringer}Утер{/link}у всю войну на севере и видел, как был распущен орден паладинов, как Утер был убит и как распространилась чума.
• Он обыскал каждую ферму и каждый дом Сумеречного леса в поисках семьи.
• На {link:raven-hill-cemetery}Кладбище Вороньего Холма{/link} он нашел надгробие с именем своей жены.
• В горе он убил трех служителей кладбища, а затем лишил жизни себя.]=],
		},
	},
	chapters = {
		{
			title = "Выветренная могила",
			hint = "Найдите могилу на дальнем краю Кладбища Вороньего Холма.",
			text = [=[Его похоронили быстро, без обрядов, за краем кладбища. Спустя несколько дней земля оказалась потревоженной, а могила — пустой. Историк Темнолесья, знавший рыцаря до войны, хранит книгу с его историей.]=],
		},
		{
			title = "Кольцо дочери",
			hint = "Принесите утешение на могилу рыцаря Моргана Ладимора.",
			text = [=[{link:morgan-stern}Морган{/link} умер, веря, что погибла вся его семья. Одна дочь, Сара, выжила. Когда ее кольцо положили на его могилу, на ветру зазвучал голос. Рыцарь с изумлением произнес имя дочери, и груз с его души был снят. Он отдал свой меч Архей тому, кто принес ему покой, а его последние слова были обращены к жене, Лис.]=],
		},
	},
	mentions = {
		{ text = "Выветренная могила" },
		{ text = "Морган Ладимор" },
		{ text = "Мор'Ладим" },
		{ text = "Любовь дочери" },
	},
	bonds = {
		{ id = "sarah-ladimore", name = "Сара Ладимор", note = "его дочь" },
		{ id = "sirra-von-indi", name = "Сирра Фон'Инди", note = "знал его до войны" },
		{ id = "commander-althea-ebonlocke", name = "Командир Алтея Чернодрев", note = "охотилась на него" },
		{ id = "uther-the-lightbringer", name = "Утер Светоносный", note = "паладин, которому он служил" },
	},
})

Translate("ruRU", "sven-yorgen", {
