		{ text = "Возвращение к Свену" },
		{ text = "В поисках мудрости" },
		{ text = "{link:morbent-fel}Морбент Фел{/link}" },
	},
	bonds = {
		{ id = "morbent-fel", name = "Морбент Фел", note = "его враг" },
		{ id = "jitters", name = "Джиттерс", note = "видел гибель его семьи" },
	},
})

