	allegiance = "Темнолесье",
	aliases = { "Аветта" },
	sections = {
		{
			title = "Обзор",
			text = [=[Аветта Феллвуд делает луки в {link:darkshire}Темнолесье{/link}. Недавно она усыновила мальчика по имени Джереми Сердцеплет, который пережил падение королевства {link:lordaeron}Лордерон{/link} и был привезен в приют в {link:stormwind-city}Штормград{/link}е. Джереми не говорит со дня нападения на его город. Его отец, Эдвард, восстал среди {link:forsaken}Отрекшихся{/link} и каждую неделю искал в руинах столицы тело сына, но однажды он не вернулся. Его последнее письмо, запятнанное кровью, попало к мастерице.]=],
