Translate("ruRU", "the-night-watch", {
	title = "Ночной Дозор",
	aliases = { "дозорные" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ночной Дозор — ополчение Темнолесья. Его собрали, когда скверная магия просочилась в {link:duskwood}Сумеречный лес{/link}, а {link:stormwind-city}Штормград{/link} отозвал своих стражников домой. С тех пор {link:morgan-s-vigil}Дозор{/link} — все, что стоит между городом и лесом. Его возглавляет командир {link:commander-althea-ebonlocke}Алтея Чернодрев{/link}, а его бойцов называют дозорными.]=],
		},
		{
			title = "Дозорные",
			text = [=[{link:morgan-s-vigil}Дозор{/link}ные охраняют ворота и площадь Темнолесья, а немногие держат одинокие посты на дорогах: двое на западной дороге, один на северной, рядом с гоблином-торговцем. Их слишком мало, и они это знают. Командир не может отсылать их далеко от города. Когда на кладбищах встают мертвецы, ей приходится просить чужаков пойти вместо них. Мертвый рыцарь {link:mor-ladim}Мор'Ладим{/link} убил нескольких ее сильнейших бойцов.]=],
		},
		{
			title = "Дозор и мир",
			text = [=[{link:darkshire}Темнолесье{/link} привыкло полагаться на {link:morgan-s-vigil}Дозор{/link} как на свое единственное войско. Когда мировой судья {link:magistrate-solomon}Соломон{/link} из Приозерья умолял о нем мэра, {link:lord-ello-ebonlocke}лорд Чернодрев{/link} отказал: если Дозор уйдет, город падет раньше, чем тот дойдет до края леса. Не все им восхищаются. Охотник {link:calor}Калор{/link} ушел из Дозора к семье {link:carevin-family}Каревин{/link}ов, назвав его благодушным. Среди дозорных — {link:sarah-ladimore}Сара Ладимор{/link}, дочь павшего рыцаря, и, по преданиям Вороньего Холма, лучник Меррик {link:the-valor-family}Валор{/link}.]=],
		},
	},
})

