	aliases = { "Ночная Погибель", "воргены стаи Ночной Погибели" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ночная Погибель — это {red:worgen}воргены{/red} Сумеречного леса: {link:ogres}огр{/link}омные люди-волки, которые стаями охотятся в южной половине леса. {link:weaver}Ткач{/link}и теней и темные бегуны рыщут по {link:holy-light}Свет{/link}лой роще и Гниющему саду. Сильнейшие из них, мерзкие клыки и оскверненные, жгут свои костры у пещер юга и в руднике {link:roland-s-doom}Погибель Роланда{/link}.]=],
		},
		{
			title = "Их приход",
			text = [=[Воргены были здесь не всегда. Охотники Темнолесья говорят, что они появились словно из воздуха, а первых нашли в Погибели Роланда. Рудокоп из этого рудника, человек по прозвищу {link:jitters}Джиттерс{/link}, рассказывает, как это случилось. Он нашел древко косы в груде обломков и вытащил его. В ту ночь воргены полезли из каждой дыры и с каждого уступа в штольнях, и большинство рудокопов погибло. Косу он потерял во время бегства. Он не знает, он ли привел людей-волков в {link:duskwood}Сумеречный лес{/link}, но боится этого.

Этой косой была {red:scythe-of-elune}Коса Элуны{/red}. Жрица ночных эльфов Велинда Звездная Песнь принесла ее в эти леса, и о судьбе жрицы узнали в руднике. Часовых {link:darnassus}Дарнасса{/link} встревожило, что дар их богини покинул руки ее служителей.]=],
		},
		{
			title = "Война против них",
			text = [=[{link:carevin-family}Семья Каревинов{/link} и их охотник {link:calor}Калор{/link} ведут бесконечную войну со стаей Ночной Погибели. На место каждой уничтоженной стаи вскоре приходит новая. Никто в {link:darkshire}Темнолесье{/link} пока не знает, какая сила их притягивает.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна хроника этих дней не объясняет, как коса призвала воргенов и в родстве ли Ночная Погибель с воргенами {link:silverpine-forest}Серебряного бора{/link}.]=],
		},
	},
})

Translate("ruRU", "the-valor-family", {
	title = "Семья Валоров",
	aliases = { "Валор" },
	sections = {
		{
			title = "Обзор",
			text = [=[Семья Валоров защищала {link:raven-hill}Вороний Холм{/link} до его падения. Том, найденный в разоренной деревне, {i}Воспоминания о Валорах{/i}, описывает их одного за другим. Его автор скорбит о них и винит себя в том, что их больше нет.]=],
		},
		{
			title = "Семья",
			text = [=[• {b}Лорд Грант Валор.{/b} Глава семьи и предводитель Вороньего Холма. Когда в лес пришла тьма, он первым сплотил жителей деревни. Нежить он ненавидел больше всех врагов и сам обходил кладбища. Тяжелая рана, полученная от нее, так по-настоящему и не зажила.
• {b}Леди Кассандра Валор.{/b} Его жена. О ней известно немногое, кроме ее любви к семье.
• {b}Сильвия Валор.{/b} Стражница Вороньего Холма, прославившаяся тем, что предавала мечу разбойников и мошенников. Говорят, она никогда не оставляла ферм Сумеречного леса.
• {b}Айра Валор.{/b} Когда ее отец занемог, она ушла в лес добывать пищу и полюбила темную чащу больше деревни. Заблудившиеся путники рассказывают о тени, которая выводит их обратно на дорогу.
• {b}Меррик Валор.{/b} Младший сын. Он вступил в {link:the-night-watch}Ночной Дозор{/link} и охранял дороги со своим луком.]=],
		},
		{
			title = "Их призраки",
			text = [=[Семья Валоров исчезла вся разом. Теперь их духи бродят по лесу, все еще занятые тем, что делали при жизни: Грант — среди скелетов кладбища, Сильвия — возле ферм, Айра — в чаще, Меррик — на дорогах. {link:sirra-von-indi}Сирра Фон'Инди{/link}, историк Темнолесья, считает, что к этому миру их привязывает некое общее горе.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Что постигло семью Валоров и что удерживает их духов, пока неизвестно.]=],
		},
	},
})

Translate("ruRU", "carevin-family", {
	title = "Семья Каревинов",
	aliases = { "Каревин", "дом Каревинов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Семья Каревинов — дом из Темнолесья, который ведет собственную войну. Они охотятся на демонов, нежить и всех, кто им помогает, и не доверяют никому, кто не желает помочь их делу. Их глава — {link:jonathan-carevin}Джонатан Каревин{/link}. Его охотник {link:calor}Калор{/link}, прежде служивший в Ночном {link:morgan-s-vigil}Дозор{/link}е, ведет борьбу с воргенами Ночной Погибели.]=],
		},
		{
			title = "Домочадцы",
			text = [=[Элейн Каревин печется о нуждах городских изгоев. Она посылает припасы на запад, в лагерь {link:sven-yorgen}Свен{/link}а Йоргена: его она называет человеком, который делает дело {link:holy-light}Свет{/link}а. Она тревожится и о старом отшельнике, который больше не приходит на рынок. Скотт Каревин торгует грибами на площади, а у дома играет маленький мальчик, Бенджамин.]=],
		},
		{
			title = "Семья Каревинов и Дозор",
			text = [=[Семья Каревинов не выступает против Ночного {link:morgan-s-vigil}Дозор{/link}а открыто. Но {link:calor}Калор{/link} не скрывает своего презрения к нему. Он мечтает о дне, когда сторонников семьи Каревинов станет больше, чем дозорных.]=],
		},
	},
})
